(()=>{'use strict';
const links=[['home','首页','index.html'],['workshop','融卡工坊','workshop.html'],['shop','周边商店','shop.html'],['collection','收藏室','collection.html'],['mailbox','岛主信箱','mailbox.html'],['office','事务所','office.html'],['resident','个人中心','resident.html'],['guide','登岛导览','guide.html']];
const key=document.body.dataset.page||'home';const h=(title,lead)=>'<header class="page-title"><span class="eyebrow">不吱岛 2.0 · 独立页面</span><h1>'+title+'</h1><p>'+lead+'</p></header>';const link=(id,label,style='button')=>'<a class="'+style+'" href="'+links.find(x=>x[0]===id)[2]+'">'+label+'</a>';
const cards=[['SR','海风来信'],['R','贝壳耳语'],['N','小岛邮戳']]; const sample=cards.map((x,i)=>'<button type="button" class="card-select" data-card="'+i+'" aria-pressed="'+(i===0?'true':'false')+'"><span class="status">'+x[0]+' · 演示</span><strong>'+x[1]+'</strong><small>仅占位，不代表账户拥有</small></button>').join('');
const pages={
home:()=>'<section class="home-birthday" aria-label="吱吱生日主题首页"><div class="home-birthday-scene"><span class="eyebrow">不吱岛 · 当期主题</span><h1>吱吱生日季</h1><p>蓝鸟花与海风，为你留了一张靠海的位置。</p><div class="placeholder home-art-slot">吱吱主视觉、屁宝、肥啾与海岛环境 · 待设计楼替换</div><div class="actions">'+link('workshop','融卡工坊','button primary')+link('shop','周边兑换')+'</div></div><div class="home-birthday-desk"><p class="eyebrow">岛主生日书桌 · 来信 / 回忆 / 赴约</p><section class="surface" aria-label="生日邀请交互"><p class="eyebrow">菜菜陪伴 · 吱吱为主角</p><p>生日来信和回忆都在首页通过标签切换，不需要跳去另一张生日页面。</p><div class="section"><div class="tabs" role="tablist" aria-label="生日书桌"><button type="button" class="button" id="letter-tab" role="tab" aria-controls="letter-panel" aria-selected="true" tabindex="0">来信</button><button type="button" class="button" id="memory-tab" role="tab" aria-controls="memory-panel" aria-selected="false" tabindex="-1">回忆</button><button type="button" class="button" id="visit-tab" role="tab" aria-controls="visit-panel" aria-selected="false" tabindex="-1">赴约</button></div><section class="section" role="tabpanel" id="letter-panel" aria-labelledby="letter-tab" tabindex="0"><h2>写给吱吱的一小页</h2><p>生日信件文案待岛主确认；这里暂不代表公开祝福或真实用户留言。</p><details><summary>展开示例内容</summary><p>愿每次回到小岛，都有人记得这一天的海风。</p></details></section><section class="section" role="tabpanel" id="memory-panel" aria-labelledby="memory-tab" tabindex="0" hidden><h2>把喜欢收进回忆</h2><p>卡面由视觉侧提供或复用经过确认的已有卡面，不臆造限定池。</p>'+link('collection','打开独立收藏室')+'</section><section class="section" role="tabpanel" id="visit-panel" aria-labelledby="visit-tab" tabindex="0" hidden><h2>从这里赴约</h2><p>活动、认证与任务各有独立入口；是否开放以正式服务端状态为准。</p><div class="actions">'+link('office','岛民事务所')+link('guide','登岛导览')+'</div></section></div></section></div></section>',
workshop:()=>h('融卡工坊','独立操作工作台：素材选择、规则说明、结果预览、确认。未确认合成规则之前禁止真实交易。')+'<div class="layout"><section class="surface"><h2>卡牌选择台</h2><ol class="steps"><li>1 选择卡片</li><li>2 核对规则</li><li>3 确认结果</li></ol><div class="card-list">'+sample+'</div><div class="notice section" id="selection-summary" role="status">已选演示卡牌：海风来信</div></section><aside class="stack"><section class="surface"><h2>规则核对区</h2><p class="muted">需要多少张卡、是否允许重复、金币消耗、产出什么卡：全部待岛主确认。此处不臆造数据。</p><div class="placeholder">合成结果预览素材位</div></section><section class="surface"><h2>操作保护</h2><p>没有余额改写、扣卡、API 调用或真实合成。</p><button class="button primary" type="button" disabled>规则待确认 · 无法融卡</button></section></aside></div>',
shop:()=>h('周边兑换商店','独立商店页面。商品、库存、资格和兑换材料均以未来确认的规则和后台数据为准。')+'<div class="layout"><section class="surface"><h2>周边陈列</h2><div class="shop-items">'+[['生日纪念卡','商品位 A'],['小岛信物','商品位 B']].map(x=>'<article class="shop-item"><div class="placeholder">'+x[1]+'：由视觉设计替换真实商品图</div><strong>'+x[0]+'</strong><span class="status">信息待确认</span><button class="button" disabled>暂不可兑换</button></article>').join('')+'</div></section><aside class="stack"><section class="surface"><h2>筛选与须知</h2><label class="field">类型<select id="shop-filter"><option value="all">全部演示商品</option><option value="card">卡片类</option><option value="other">其他类</option></select></label><p id="shop-message" role="status" class="muted">目前没有接入正式库存。</p></section><section class="surface"><h2>兑换确认流程</h2><ol class="steps"><li>选择商品</li><li>核验资格</li><li>确认消耗</li><li>登记记录</li></ol><p>未来必须支持取消、重复提交保护与交易记录查询。</p></section></aside></div>',
collection:()=>h('回忆收藏室','画廊骨架。保留往期卡牌与收藏功能的独立入口，未来由真实会话读取用户收藏。')+'<section class="surface"><div class="actions"><label class="field">筛选稀有度<select id="rarity"><option value="all">全部</option><option value="SR">SR</option><option value="R">R</option><option value="N">N</option></select></label></div><div id="collection-grid" class="card-list section"></div><p class="muted">所有卡片均为静态演示，无真实库存或获得日期。</p></section>',
mailbox:()=>h('岛主信箱','独立来信空间。匿名、实名、后台回复及持久化由后续正式接口负责，预览不会保存或发送任何信息。')+'<div class="layout"><section class="surface"><h2>写给岛主的一封信</h2><div class="fields"><label class="field">署名方式<select id="sender"><option>岛民署名（演示）</option><option>匿名（演示）</option></select></label><label class="field">来信内容<input id="message" type="text" maxlength="200" placeholder="这里只练习输入，不会发送"></label><button class="button" type="button" id="preview-letter">预览信件</button></div><p class="muted" id="letter-feedback" role="status">演示环境：不发送、不存储。</p></section><aside class="surface"><h2>岛主回复展板</h2><div class="placeholder">真实回复、可见范围与审核规则待接入</div></aside></div>',
office:()=>h('岛民事务所','任务入口与活动开放状态展示骨架。保留原任务逻辑，不新增任何可领金币的模拟任务。')+'<section class="surface"><h2>事务公告</h2><div class="list"><article><strong>本期活动状态</strong><p>需接入真实活动开关；不可仅依赖固定文案判断。</p></article><article><strong>任务与奖励</strong><p>正式任务由业务服务端决定，本预览无领取入口。</p></article><article><strong>历史任务</strong><p>原有历史记录不可覆盖或清空。</p></article></div></section>',
resident:()=>h('岛民个人中心','账户信息、认证、卡牌、金币记录的容器骨架。预览不要求登录，不会读取正式用户资料。')+'<div class="layout"><section class="surface"><h2>岛民档案</h2><div class="placeholder">OC 肖像与岛民身份信息素材位</div><p>身份、认证与居住岛屿信息都需要真实登录会话。</p></section><aside class="surface"><h2>我的记录</h2><div class="list"><article>金币账本 · 只读接入点</article><article>收藏记录 · 只读接入点</article><article>兑换记录 · 只读接入点</article></div></aside></div>',
guide:()=>h('登岛导览','新岛民的独立上手页面；引导页面而非真实注册或认证流程。')+'<section class="surface"><h2>登岛路径</h2><div class="tiles">'+[['resident','先认识自己的岛民档案'],['office','再看岛上事务'],['collection','最后收藏小岛回忆']].map((x,i)=>'<a class="tile" href="'+links.find(v=>v[0]===x[0])[2]+'"><strong>第 '+(i+1)+' 站</strong><p>'+x[1]+'</p></a>').join('')+'</div></section>'
};
const nav=(a)=>'<a href="'+a[2]+'" '+(a[0]===key?'aria-current="page"':'')+'>'+a[1]+'</a>';document.querySelector('#app').innerHTML='<div class="site"><header class="masthead"><a class="brand" href="index.html">不吱岛<small>BUZHI ISLAND · 2.0</small></a><nav class="nav" aria-label="站点导航">'+links.map(nav).join('')+'</nav><div class="controls"><button id="motion" class="button" type="button" aria-pressed="false">减少动效</button></div></header><div class="banner" role="status">工程结构预览 · 未接入正式账户、卡池、金币或兑换服务 · 所有操作均为本地演示</div><details class="mobile-more"><summary>全部页面导航 · 当前：' + links.find(x=>x[0]===key)[1] + '</summary><nav class="mobile-more-links" aria-label="全部页面导航">' + links.map(nav).join('') + '</nav></details><main id="content">'+pages[key]()+'</main><footer class="site-footer">不吱岛 · 双岛主：菜菜与吱吱　｜　2.0 多页面工程骨架 · 不可作为正式交易入口</footer></div><nav class="mobile-nav" aria-label="手机导航">'+['home','office','workshop','collection','resident'].map(k=>nav(links.find(x=>x[0]===k))).join('')+'</nav>';
const tabs=[...document.querySelectorAll('[role="tab"][aria-controls]')];function setBirthdayTab(id,focus=false){const target=tabs.find(t=>t.getAttribute('aria-controls')===id);if(!target)return;tabs.forEach(t=>{const active=t===target;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;const panel=document.getElementById(t.getAttribute('aria-controls'));if(panel)panel.hidden=!active});if(focus)target.focus()}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setBirthdayTab(tab.getAttribute('aria-controls')));tab.addEventListener('keydown',e=>{let idx;if(e.key==='ArrowRight')idx=(i+1)%tabs.length;else if(e.key==='ArrowLeft')idx=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')idx=0;else if(e.key==='End')idx=tabs.length-1;else return;e.preventDefault();setBirthdayTab(tabs[idx].getAttribute('aria-controls'),true)})});if(tabs.length&&location.hash)setBirthdayTab(location.hash.slice(1));
const motion=document.querySelector('#motion');motion.addEventListener('click',()=>{const yes=document.body.classList.toggle('reduce-motion');motion.setAttribute('aria-pressed',String(yes));motion.textContent=yes?'恢复动效':'减少动效'});
document.querySelectorAll('[data-card]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-card]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));document.querySelector('#selection-summary').textContent='已选演示卡牌：'+btn.querySelector('strong').textContent}));
const rarity=document.querySelector('#rarity');const render=()=>{if(!rarity)return;const v=rarity.value;document.querySelector('#collection-grid').innerHTML=cards.filter(x=>v==='all'||x[0]===v).map(x=>'<article class="tile"><span class="status">'+x[0]+'</span><strong>'+x[1]+'</strong><p>演示卡面占位</p></article>').join('')};if(rarity){rarity.addEventListener('change',render);render()}
const sf=document.querySelector('#shop-filter');if(sf)sf.addEventListener('change',()=>{document.querySelector('#shop-message').textContent='筛选演示：'+sf.options[sf.selectedIndex].text+'。商品信息未绑定库存。'});
const letter=document.querySelector('#preview-letter');if(letter)letter.addEventListener('click',()=>{const str=document.querySelector('#message').value.trim();document.querySelector('#letter-feedback').textContent=str?'预览字数：'+Array.from(str).length+' 字；没有发送也没有保存。':'请先输入内容以查看演示字数。'});
})();